  createdAt: '2025-12-16',
  lastUpdated: '2025-12-16',
  basedOn: 'ootday_persona/Persona.md',
  description: 'OOT AI Fashion Friend persona with bestie personality, Thai-English code-switching, and conversation dynamics',
};

