/**
 * Guardrail Redirect Responses for System Prompt v2.0
 *
 * Polite redirect messages for off-topic queries.
 * These messages maintain friendliness while redirecting users back to fashion topics.
 *
 * @version 1.0.0
 * @created 2025-10-14
 */

import type { RedirectMessageMap, GuardrailCategory } from '../types/chat-types';

/**
 * Redirect Messages by Category
 *
 * Each message:
 * 1. Acknowledges the question politely
 * 2. Clearly states the assistant's fashion focus
 * 3. Suggests a fashion-related alternative
 */
export const REDIRECT_MESSAGES: RedirectMessageMap = {
  health:
    'เรื่องนี้ฉันไม่ถนัดเลยค่ะ แต่ถ้าเป็นเรื่องแฟชั่น สไตล์การแต่งตัว ฉันช่วยได้เต็มที่เลย! 👗',

  technology:
    'อันนี้ไม่ใช่ความเชี่ยวชาญของฉันเลยค่ะ แต่ถ้าอยากรู้ว่าจะใส่อะไรไปซื้อ gadget ใหม่ บอกได้เลย! 😄',

  food: 'ฉันแนะนำเรื่องแฟชั่นนะคะ ร้านอาหารไม่ค่อยรู้เรื่อง 😊 แต่ถ้าอยากรู้ว่าใส่ชุดอะไรไปร้านหรูๆ บอกได้เลย!',

  general:
    'ขอโทษนะคะ ฉันเป็นผู้ช่วยด้านแฟชั่นค่ะ ไม่ค่อยเชี่ยวชาญเรื่องอื่นเท่าไหร่ 😅 มีอะไรให้ช่วยเรื่องเสื้อผ้าหรือชุดมั้ยคะ?',

  travel:
    'สถานที่ท่องเที่ยวฉันไม่แม่นค่ะ แต่ถ้าอยากรู้ว่าควรใส่ชุดแบบไหนไปเที่ยว[destination] ฉันช่วยได้เต็มที่เลย! ✈️',

  inappropriate: 'ขอโทษนะคะ ฉันไม่สามารถตอบคำถามนี้ได้ค่ะ มีอะไรให้ช่วยเรื่องแฟชั่นมั้ยคะ?',

  default:
    'ขอโทษนะคะ ฉันเป็นผู้ช่วยด้านแฟชั่นค่ะ ไม่ค่อยเชี่ยวชาญเรื่องอื่นเท่าไหร่ 😅 มีอะไรให้ช่วยเรื่องเสื้อผ้าหรือชุดมั้ยคะ?',
};

/**
 * Alternative redirect messages for variety
 * Use these when user repeatedly asks off-topic questions
 */
export const ALTERNATIVE_REDIRECTS: Record<GuardrailCategory, string[]> = {
  health: [
    'เรื่องนี้ฉันไม่ถนัดเลยค่ะ แต่ถ้าเป็นเรื่องแฟชั่น สไตล์การแต่งตัว ฉันช่วยได้เต็มที่เลย! 👗',
    'สุขภาพฉันไม่แม่นค่ะ แต่ถ้าอยากดูดีและรู้สึกดี ฉันช่วยเรื่องแต่งตัวได้เลย! 💪✨',
  ],
  technology: [
    'อันนี้ไม่ใช่ความเชี่ยวชาญของฉันเลยค่ะ แต่ถ้าอยากรู้ว่าจะใส่อะไรไปซื้อ gadget ใหม่ บอกได้เลย! 😄',
    'เทคโนโลยีฉันไม่ค่อยเข้าใจค่ะ แต่แฟชั่นเท็คนิค ฉันช่วยได้เต็มที่! 👔💻',
  ],
  food: [
    'ฉันแนะนำเรื่องแฟชั่นนะคะ ร้านอาหารไม่ค่อยรู้เรื่อง 😊 แต่ถ้าอยากรู้ว่าใส่ชุดอะไรไปร้านหรูๆ บอกได้เลย!',
    'อาหารฉันกินเก่งแต่แนะนำไม่เก่งค่ะ 😄 แต่ถ้าเป็นชุดไปดินเนอร์ ฉันช่วยได้เลย!',
  ],
  general: [
    'ขอโทษนะคะ ฉันเป็นผู้ช่วยด้านแฟชั่นค่ะ ไม่ค่อยเชี่ยวชาญเรื่องอื่นเท่าไหร่ 😅 มีอะไรให้ช่วยเรื่องเสื้อผ้าหรือชุดมั้ยคะ?',
    'เรื่องนั้นฉันไม่แน่ใจค่ะ แต่ถ้าเป็นเรื่องแฟชั่น สไตล์ หรือการแต่งตัว ฉันช่วยได้เต็มที่! 👗✨',
  ],
  travel: [
    'สถานที่ท่องเที่ยวฉันไม่แม่นค่ะ แต่ถ้าอยากรู้ว่าควรใส่ชุดแบบไหนไปเที่ยว[destination] ฉันช่วยได้เต็มที่เลย! ✈️',
    'ที่เที่ยวฉันไม่รู้จักมากค่ะ แต่ชุดเที่ยวไปที่ไหนก็ช่วยได้เลย! 🧳✨',
  ],
  inappropriate: [
    'ขอโทษนะคะ ฉันไม่สามารถตอบคำถามนี้ได้ค่ะ มีอะไรให้ช่วยเรื่องแฟชั่นมั้ยคะ?',
  ],
  default: [
    'ขอโทษนะคะ ฉันเป็นผู้ช่วยด้านแฟชั่นค่ะ ไม่ค่อยเชี่ยวชาญเรื่องอื่นเท่าไหร่ 😅 มีอะไรให้ช่วยเรื่องเสื้อผ้าหรือชุดมั้ยคะ?',
    'เรื่องนี้ฉันไม่ถนัดค่ะ แต่ถ้าเป็นเรื่องแฟชั่นหรือสไตล์ ฉันช่วยได้เลย! 💕',
  ],
};

/**
 * Fashion-Adjacent Topic Examples (ALLOWED)
 *
 * These topics mention other contexts but are fashion-related
 */
export const FASHION_ADJACENT_EXAMPLES = [
  'What shoes to wear to a marathon?',
  'How to pack clothes for travel?',
  'What to wear to a restaurant?',
  'Outfit for job interview?',
  'What to wear to a wedding?',
  'Gym outfit recommendations?',
  'Beach vacation outfits?',
  'Concert outfit ideas?',
];

/**
 * Helper function to get redirect message
 */
export function getRedirectMessage(category: GuardrailCategory): string {
  return REDIRECT_MESSAGES[category] || REDIRECT_MESSAGES.default;
}

/**
 * Helper function to get alternative redirect message
 * Use when user asks off-topic questions multiple times
 */
export function getAlternativeRedirect(
  category: GuardrailCategory,
  attemptNumber: number = 0
): string {
  const alternatives = ALTERNATIVE_REDIRECTS[category] || ALTERNATIVE_REDIRECTS.default;
  const index = attemptNumber % alternatives.length;
  return alternatives[index];
}

/**
 * Check if a topic is fashion-adjacent (allowed)
 */
export function isFashionAdjacent(message: string): boolean {
  const lowerMessage = message.toLowerCase();

  // Check for "what to wear to..." pattern
  if (/(?:what|อะไร|ใส่|แต่ง).*(?:wear|ใส่).*(?:to|ไป|ที่)/i.test(lowerMessage)) {
    return true;
  }

  // Check for packing/travel with clothes context
  if (
    /(?:pack|เก็บ|เตรียม).*(?:clothes|เสื้อผ้า|ชุด)/i.test(lowerMessage) ||
    /(?:clothes|เสื้อผ้า|ชุด).*(?:pack|เก็บ|เตรียม)/i.test(lowerMessage)
  ) {
    return true;
  }

  // Check for outfit/dress code context
  if (/(?:outfit|ชุด|dress code|แต่งตัว).*(?:for|สำหรับ|ไป)/i.test(lowerMessage)) {
    return true;
  }

  return false;
}

/**
 * Export all for convenience
 */
export default {
  REDIRECT_MESSAGES,
  ALTERNATIVE_REDIRECTS,
  FASHION_ADJACENT_EXAMPLES,
  getRedirectMessage,
  getAlternativeRedirect,
  isFashionAdjacent,
};

